      title: '3장 핵심 요구사항 — 단계별 체크리스트',
      tag: '3장',
      summary: '계획·적입·위험물·고정·완료·적출 단계별로 꼭 할 일과 하지 말 일, Cubestow가 돕는 범위.',
      body: `
      <p>3장은 CTU Code 전체를 한 쪽 반 분량의 "할 일 / 하지 말 일" 목록으로 압축한 장입니다(§3.1~3.7). 세부 근거는 뒤의 장과 부속서에 있지만, 현장 책임자가 작업 전후에 훑어보는 점검표로 쓰기 좋습니다. 아래는 단계별로 묶어 실무 순서대로 정리한 것입니다.</p>
      <h3>단계별 핵심</h3>
      <table class="lib-table"><thead><tr><th>단계</th><th>할 일</th><th>하지 말 일</th></tr></thead><tbody>
      <tr><td>일반(§3.1)</td><td>안전한 작업 환경과 취급 장비, 알맞은 개인보호구. CTU와 고정 장비가 양호한지 점검</td><td>적입·고정·적출 중 흡연, 음식물 섭취</td></tr>
      <tr><td>계획(§3.2)</td><td>운송에 맞는 CTU 유형 선택, 필요하면 적입 계획 작성, 화물·운송 방식·CTU에 맞는 고정 방법 선택</td><td>CTU의 허용 적재중량, CSC와 국내 도로·철도 규정의 최대 총중량 초과</td></tr>
      <tr><td>적입(§3.3)</td><td>무거운 화물을 바닥 전체에 분산, "이 면을 위로" 같은 취급 표시 준수, 무게중심을 올바른 위치에</td><td>좁은 면적에 무게 집중, 편심 적재, 피할 수 있는데 불규칙한 층 쌓기, 가벼운 화물 위에 무거운 화물, 냄새 옮기는 화물과 민감한 상품 함께 적재, 젖은 화물 적입, 화물과 맞지 않는 고정·보호 장비</td></tr>
      <tr><td>위험물(§3.4)</td><td>포장 표시·라벨 확인, 위험물 규정대로 적입, 가능하면 문 가까이, CTU 외부에 표찰·표시 부착</td><td>격리 대상 화물 혼적, 손상된 포장 적입</td></tr>
      <tr><td>고정(§3.5)</td><td>필요하면 빈 공간 채우기, 블로킹·래싱으로 모든 방향의 미끄럼과 전도 방지, 힘을 넓은 면적에 분산, 필요하면 품목별 개별 고정, 미끄럼 방지재, 훅·섀클 사용</td><td>CTU 구조·화물·고정 장치에 과도한 응력, 포장이 상할 만큼 과도한 조임, 웨빙 래싱을 매듭으로 체결</td></tr>
      <tr><td>완료(§3.6)</td><td>올바른 총중량 확정, 필요하면 봉인, CTU 번호·총중량·봉인 번호를 서류에 기재, 필요하면 적입 증명서</td><td>—</td></tr>
      <tr><td>적출(§3.7)</td><td>번호·봉인을 서류와 대조, 외부 누출·해충 확인, 환기 후 쏟아짐에 대비해 개문, 꺼내며 손상 기록, 고정재 제거·청소·이전 표찰 제거로 마무리</td><td>—</td></tr>
      </tbody></table>
      <h3>현장 체크포인트</h3>
      <ol>
      <li>적입 전에 CTU 상태(구조 손상, 청결·건조)와 쓸 고정 장비를 먼저 봅니다. 화물보다 CTU가 먼저입니다.</li>
      <li>중량 한도는 세 가지를 모두 봅니다: CTU 명판의 적재중량, 최대 총중량, 도로 운송 한도. 도로 한도가 가장 낮은 경우가 많습니다.</li>
      <li>무게중심과 바닥 집중하중은 "편심 금지"와 "좁은 면적 집중 금지"로 따로 적혀 있습니다. 둘 다 확인합니다.</li>
      <li>고정의 기준은 "어느 방향으로도" 미끄러지거나 넘어지지 않는 것입니다. 문쪽 방향이 가장 자주 빠집니다.</li>
      <li>완료 단계의 총중량·봉인 번호·CTU 번호는 서류에 들어가야 끝난 것입니다.</li>
      </ol>
      <h3>Cubestow 적용</h3>
      <table class="lib-table"><thead><tr><th>3장 항목</th><th>Cubestow가 하는 것</th></tr></thead><tbody>
      <tr><td>CTU 유형·적입 계획</td><td>20ft·40ft·40ft HC·45ft HC 드라이 컨테이너(와 한국 도로 한도 항목) 중에서 고른 규격으로 대수, 3D 배치, 적재 순서, PDF 작업지시서를 만듭니다. 오픈탑·플랫랙·냉동 컨테이너와 트레일러는 다루지 않습니다.</td></tr>
      <tr><td>중량 한도</td><td>화물 합계가 컨테이너 최대 적재중량을 넘는 배치는 만들지 않습니다(하드 조건). 기본 값은 대표값(예: 20ft 28,200kg)이라 실제 명판과 다를 수 있습니다.</td></tr>
      <tr><td>무게중심·분산</td><td>총중량 기준 중심 편차(±5% 양호, ±10% 주의), 길이 50%에 실린 질량 60% 이하, 수직 무게중심(높이의 50% 초과 주의, 60% 초과 위험), 바닥 선하중(1m당 20ft 4.5t, 40ft·45ft 3.0t 초과 시 받침목 검토)을 봅니다.</td></tr>
      <tr><td>취급 표시·적층</td><td>"눕힘 허용"을 켜지 않으면 위아래 방향을 유지하고, "상부 적재 금지"와 상부 허용하중(입력한 제품만)을 지킵니다. 무게만 비교해 가벼운 화물 위 무거운 화물을 막지는 않으므로, 상부 허용하중을 입력하지 않은 제품은 "미입력"으로 표시됩니다.</td></tr>
      <tr><td>고정</td><td>한 방향 빈 공간 합 15cm 초과분 채움, 에어백·충전재·바닥 각재(못 수)·래싱 줄 수를 권고하고, "CTU 기준 적용"에서는 화물마다 안쪽·좌·우를 화물이나 고정재로 막습니다. 스트랩 사전장력은 MSL의 50% 이하로 안내합니다.</td></tr>
      </tbody></table>
      <p><b>계산하지 않는 것</b>: CTU·고정 장비 상태 점검, 개인보호구, 냄새·습기 등 화물 간 적합성, 위험물(표시·격리·표찰·적입 증명서), 총중량 확정과 봉인·서류, 적출 절차. 매듭 금지나 과도한 조임 같은 작업 방법도 현장에서 확인해야 합니다.</p>
      ${note}`
