      <tr><td>운송인에게 통보</td><td>안전 승인 명판의 허용 적층 중량이 192,000kg 미만인 컨테이너를 선박으로 보낼 때 적층 능력이 줄었다는 사실</td><td>§11.3.5</td></tr>
