      body: `
      <p>컨테이너 안에서 래싱을 거는 고리는 생각보다 약합니다. 해마다 엄청난 수의 컨테이너가 오가지만, 래싱 장비만 튼튼하게 고르고 고리 강도를 확인하지 않아 고정이 풀리는 일이 흔합니다. 이 글은 고박점의 종류와 허용하중, 그리고 고정 전체의 힘을 어떻게 셈해야 하는지 정리합니다.</p>
      <figure class="lib-figure lib-drawing"><img src="/images/ctu/anchor-points.svg" alt="문쪽에서 본 컨테이너 단면의 바닥 고박점(최소 1,000daN)과 위쪽 래싱 고리(최소 500daN) 위치, 래싱과 고박점 가운데 약한 쪽이 실제 힘을 정하는 세 가지 예" loading="lazy" decoding="async"><figcaption><span>Cubestow 도면</span> 고박점 위치는 실제 단면 비율로 그렸습니다. 래싱 한 줄이 믿을 수 있는 힘은 벨트가 아니라 가장 약한 고박점이 정합니다.</figcaption></figure>
      <h3>고박점 종류와 최소 허용하중</h3>
      <table class="lib-table"><thead><tr><th>고박점</th><th>위치</th><th>최소 허용하중(MSL)</th><th>근거</th></tr></thead><tbody>
      <tr><td>바닥 고박점(anchor point)</td><td>바닥 가장자리, 하부 측면 레일</td><td>1,000daN(약 1톤), 어느 방향이든</td><td>ISO 1496-1</td></tr>
      <tr><td>위쪽 래싱 고리(lashing point, D링)</td><td>상부 측면 레일, 측벽 위쪽</td><td>500daN(약 0.5톤)</td><td>ISO 1496-1</td></tr>
      </tbody></table>
      <p>표의 값은 <b>최소</b>입니다. 최근 제작된 컨테이너는 바닥 고박점이 2,000daN인 경우도 많지만(CTU Code 6장), 고리 각인이나 제조사 자료로 확인하지 않았다면 최소값만 믿어야 합니다.</p>
      <h3>가장 약한 곳이 전체의 한계</h3>
      <p>래싱 한 줄의 힘은 벨트·긴장기·훅·고박점 가운데 가장 약한 부품의 MSL을 넘을 수 없습니다. 빠른 래싱 가이드 §5.3도 고박점은 래싱과 같은 MSL 이상이어야 한다고 합니다.</p>
      <table class="lib-table"><thead><tr><th>예</th><th>래싱 벨트</th><th>건 곳</th><th>실제로 믿을 수 있는 힘</th></tr></thead><tbody>
      <tr><td>1</td><td>2,000daN</td><td>바닥 고박점(1,000daN)</td><td>1,000daN — 벨트 능력의 절반</td></tr>
      <tr><td>2</td><td>2,000daN</td><td>위쪽 고리(500daN)</td><td>500daN — 벨트 능력의 4분의 1</td></tr>
      <tr><td>3</td><td>4,000daN 벨트 2줄</td><td>위쪽 고리 2개</td><td>500 × 2 = 1,000daN — "8,000daN 고정"이 아님</td></tr>
      </tbody></table>
      <p>그래서 같은 화물을 위쪽 고리로 막으려면 고리를 확인했을 때보다 줄 수가 최대 4배 필요합니다. 한 고박점에 하프루프 양 끝을 모두 걸면 그 고박점은 래싱 MSL의 1.4배 이상이어야 합니다(빠른 래싱 가이드 §5.3).</p>
      <h3>현장 체크포인트</h3>
      <ul><li>고리 각인·명판·제조사 자료로 고박점 MSL을 확인합니다. 확인하지 못하면 바닥 1,000daN, 위쪽 500daN으로 셉니다.</li><li>고정 업체나 장비 공급사가 말하는 "○○daN 고정"이 벨트 능력인지, 고박점까지 포함한 값인지 계약과 계산서로 확인합니다.</li><li>무거운 화물은 위쪽 고리보다 바닥 고박점과 블로킹으로 막는 방법을 먼저 검토합니다.</li><li>고리가 휘었거나 용접이 갈라진 컨테이너는 고박점 수에서 뺍니다.</li></ul>
      <h3>Cubestow 설정 (1.1.79~)</h3>
      <ul><li>고정 조건 → 컨테이너 래싱 고박점 "확인 안 함"(기본): 바닥 1,000daN, 컨테이너 높이 절반 위의 고리 500daN까지만 래싱에 맡깁니다.</li><li>"표시 확인": 고박점이 래싱 MSL 이상이라고 보고 래싱 MSL로 계산합니다.</li><li>고박점 때문에 줄 수를 늘리면 고정재 권고에 "계산 기준 · 래싱 고박점" 안내가 붙습니다.</li></ul>
      <p class="lib-why">참고한 자료: ISO 1496-1(드라이 컨테이너 사양·시험), CTU Code 6장과 정보자료 IM5 §5.3, 컨테이너 고박점 강도와 가장 약한 곳 원칙에 관한 업계 기고.</p>
      ${note}`
