        '승인 명판과 구조 결함 확인, 화물 성질(기후·온도·중량·치수·벌크 여부)과 운송 방식(적층·도로·철도·로로선)에 맞는 CTU 선택.',
      body: `
          <p>6장이 CTU 종류별 성능을 설명했다면, 7장은 "이 화물을 이 경로로 보낼 때 이 CTU가 맞는가"를 판단하는 장입니다. 판단은 세 단계입니다. 운송에 쓸 수 있는 상태인가(§7.1), 화물에 맞는가(§7.2), 운송 방식에 맞는가(§7.3). CTU를 잘못 고르면 고정을 아무리 잘해도 메울 수 없으므로, 부킹 단계에서 먼저 정해야 하는 일입니다.</p>
      <figure class="lib-figure"><img src="/images/ctu/ctu-for-cargo-v2.webp" alt="화물에 맞는 CTU: 일반 상자는 지게차로 문을 통해 싣는 드라이, 키 큰 기계는 지붕 보를 떼어 내고 크레인으로 위에서 넣는 오픈탑, 폭이 넓은 기계는 래싱으로 고정한 플랫랙, 신선 화물은 냉동 컨테이너" loading="lazy" decoding="async"><figcaption><span>AI 생성 도해</span> 화물의 크기, 싣는 방법, 온도 조건에 맞는 CTU를 고릅니다. 위에서 싣는 화물은 오픈탑, 폭·높이를 넘는 화물은 플랫랙, 신선 화물은 냉동 컨테이너를 씁니다.</figcaption></figure>
          <h3>운송에 쓸 수 있는 CTU인가 (§7.1)</h3>
          <ul>
          <li>화물컨테이너와 유럽 철도용 스왑바디처럼 형식 승인이 필요한 CTU는 유효한 승인 명판이 없으면 운송에 쓸 수 없습니다. 종류에 따라 정기 검사나 연속 검사 확인도 필요합니다(§7.1.1, 부속서 4).</li>
          <li>상·하부 측면 레일, 단부 레일, 문턱과 헤더, 바닥 가로보, 코너 포스트, 코너 피팅 같은 구조 부재에 심각한 결함이 있는 컨테이너·스왑바디는 사람을 위험하게 하므로 쓰지 않습니다(§7.1.2, 8장).</li>
          <li>주요 구조 부재가 낡았거나 결함이 뚜렷한 도로차량·세미트레일러·철도화차도 부적합합니다(§7.1.3).</li>
          </ul>
          <h3>화물에 맞는 CTU (§7.2)</h3>
          <p>대부분의 화물은 드라이 컨테이너, 박스형 스왑바디, 트레일러로 충분합니다(§7.2.1). 원문이 따로 짚는 경우는 다음과 같습니다.</p>
          <ul>
          <li>내부 치수를 넘는 화물은 플랫폼·플랫랙, 높이만 넘으면 오픈탑입니다. 폭까지 넘으면 오픈탑도 맞지 않습니다(§7.2.6).</li>
          <li>컨테이너 바닥은 0.5kN/cm²까지 견디도록 설계되어, 지게차가 안에 들어가 싣는 포장은 지게차에 따라 약 3~3.5톤으로 제한될 수 있습니다. 그보다 무거우면 위나 옆에서 싣는 오픈탑·오픈사이드·플랫폼을 씁니다(§7.2.7).</li>
          <li>석재 블록 같은 중량물은 드라이 컨테이너 고박점 용량이 작아 골조 버팀·블로킹이 필요하고, 원목처럼 길고 불규칙한 화물은 플랫폼·플랫랙이 맞습니다(§7.2.5, §7.2.9).</li>
          <li>액체·고체 벌크를 플렉시탱크나 라이너로 일반 CTU에 실으면 문쪽 임시 격벽 같은 보강과 적재중량 제한을 지킵니다(§7.2.10, 부속서 7 제5절).</li>
          </ul>
          <h3>운송 방식에 맞는 CTU (§7.3)</h3>
          <ul>
          <li>CSC 승인을 받은 적층형 컨테이너는 기본적으로 모든 운송 방식에 쓸 수 있습니다. 다만 명판의 허용 적층 중량이 192,000kg 미만이면 선박에서 그 위에 쌓이는 무게가 한도를 넘지 않게 따로 적재해야 합니다(§7.3.1).</li>
          <li>총중량이 34톤 이상인 컨테이너·스왑바디는 일부 샤시와 철도차량이 싣지 못합니다. 무거운 컨테이너일수록 맞는 샤시·트랙터·화차를 미리 확보합니다(§7.3.1).</li>
          <li>철도 적재중량은 선로 등급에 따라 달라지므로 과적이 우려되면 철도 운영자에게 묻습니다(§7.3.2). 도로에서 철도로 옮길 스왑바디·세미트레일러는 그래플러 암으로 들 수 있고 철도 운송 승인을 받았는지 확인합니다(§7.3.3).</li>
          <li>로로선으로 보낼 때는 송하인이 CTU 운영자나 로로선 운영자에게 요건을 확인합니다. 도로차량과 세미트레일러는 차량 총중량(GVM)에 따라 한쪽 측면에 고정 지점이 있어야 합니다.</li>
          </ul>
          <table class="lib-table"><thead><tr><th>차량 총중량(GVM)</th><th>한쪽 측면 최소 고정 지점</th></tr></thead><tbody>
          <tr><td>3.5t 이상 20t 이하</td><td>2개</td></tr>
          <tr><td>20t 초과 30t 이하</td><td>3개</td></tr>
          <tr><td>30t 초과 40t 이하</td><td>4개</td></tr>
          <tr><td>40t 초과 50t 이하</td><td>5개</td></tr>
          <tr><td>50t 초과 60t 이하</td><td>6개</td></tr>
          </tbody></table>
          <p>고정 지점 하나의 최소 강도는 GVM(톤) × 10 × 1.2 ÷ n kN이고, n은 한쪽 측면의 고정 지점 수입니다(§7.3.4.2). 예를 들어 GVM 40t 차량이 한쪽에 4개를 갖췄다면 하나당 120kN 이상이어야 합니다. 트레일러가 여럿인 연결차량은 트레일러마다 따로 따지고, 트랙터는 앞쪽에 고정 지점 2개나 견인 연결구 1개를 갖춥니다(§7.3.4.3). 철도 페리로 가는 화차는 램프 꺾임각과 선내 곡선 선로를 지날 수 있어야 하며, 고정 지점과 허용 축하중은 페리 운영자에게 확인합니다(§7.3.4.4, §7.3.4.5).</p>
          <h3>Cubestow에서는</h3>
          <ul>
          <li>고를 수 있는 CTU는 드라이 컨테이너 네 가지(20ft, 40ft, 40ft HC, 45ft HC)와 그 한국 도로 한도 항목입니다. 냉동·통풍·오픈탑·플랫랙·탱크·벌크 컨테이너, 스왑바디, 트레일러, 화차는 없으므로 "드라이 컨테이너가 맞는 화물인가"는 사용자가 먼저 판단해야 합니다.</li>
          <li>제품이 고른 컨테이너 내부에 어느 방향으로도 들어가지 않거나 개당 중량이 최대 중량을 넘으면 계산 전에 무엇이 얼마나 넘는지 알려 줍니다. 이 경고가 나오면 §7.2.6에 따라 플랫랙·오픈탑을 검토할 신호입니다.</li>
          <li>승인 명판·검사 기한·구조 결함, 허용 적층 중량, 샤시·화차 능력, 로로선 고정 지점, 지게차 축하중과 바닥 접촉 압력(0.5kN/cm²), 결로와 온도 관리는 확인하지 않습니다.</li>
          </ul>
      `
