  const stripProductNotes = html => {
    const template = document.createElement('template');
    template.innerHTML = html.replaceAll('Cubestow 도면', 'AI 생성 도해');
    [...template.content.querySelectorAll('h3')]
      .filter(h => /^Cubestow(?:에서는| 적용| 설정)/i.test(h.textContent.trim()))
      .forEach(h => {
        let node = h.nextElementSibling;
        while (node && node.tagName !== 'H3') {
          const next = node.nextElementSibling;
          node.remove();
          node = next;
        }
        h.remove();
      });
    template.content.querySelectorAll('p, li').forEach(node => {
      if (/Cubestow/i.test(node.textContent)) node.remove();
    });
    template.content.querySelectorAll('figcaption').forEach(node => {
      node.innerHTML = node.innerHTML.replace(/\s*Cubestow[^.]*\./gi, '');
    });
    return template.innerHTML;
  };
  DOCS.forEach(doc => (doc.body = stripProductNotes(doc.body)));
